function t(k,...a){let s=(I18N[LANG]&&I18N[LANG][k]);if(s==null)s=I18N.en[k];if(s==null)return k;return a.length?s.replace(/\{(\d)\}/g,(_,i)=>a[+i]??''):s;}
// 1.54.9, the owner: "numbered pins instead of Home / Work / Kids — let people rename them how they want". Four pins
// (the storage keeps its old slot ids, so nobody loses a place); a name of the reader's own, in localStorage only.
const SLOT_ORDER=['home','work','kids','pin'];
function slotNames(){ try{ const o=JSON.parse(localStorage.getItem('slot_names')||'{}'); return o&&typeof o==='object'?o:{}; }catch(e){ return {}; } }
function slotName(id){ const n=String(slotNames()[id]||'').trim(); return n||t('sl_n',SLOT_ORDER.indexOf(id)+1); }
function setSlotName(id,v){ try{ const o=slotNames(); v=String(v||'').replace(/\s+/g,' ').trim().slice(0,24); if(v) o[id]=v; else delete o[id]; localStorage.setItem('slot_names',JSON.stringify(o)); }catch(e){} }
// plural: key_1 / key_n (en, fr) — uk also key_2 (2–4) / key_5 (5+, 11–14)
function tn(k,n){const d=I18N[LANG]||I18N.en; let f; if(LANG==='uk'){const m10=n%10,m100=n%100; f=(m10===1&&m100!==11)?'_1':(m10>=2&&m10<=4&&!(m100>=12&&m100<=14))?'_2':'_5';} else f=(n===1||(LANG==='fr'&&n===0))?'_1':'_n';
  let s=d[k+f]??d[k+'_n']??d[k+'_5']??I18N.en[k+f]??I18N.en[k+'_n']; return (s||k).replace('{0}',n);}
// oblast short names by uid: [en, uk, fr]
const OBL_N={'23':['Kherson','Херсонська','Kherson'],'8':['Volyn','Волинська','Volhynie'],'5':['Rivne','Рівненська','Rivne'],'10':['Zhytomyr','Житомирська','Jytomyr'],'14':['Kyiv','Київська','Kyiv'],'25':['Chernihiv','Чернігівська','Tchernihiv'],'20':['Sumy','Сумська','Soumy'],'22':['Kharkiv','Харківська','Kharkiv'],'16':['Luhansk','Луганська','Louhansk'],'28':['Donetsk','Донецька','Donetsk'],'12':['Zaporizhzhia','Запорізька','Zaporijjia'],'27':['Lviv','Львівська','Lviv'],'13':['Ivano-Frankivsk','Івано-Франківська','Ivano-Frankivsk'],'11':['Zakarpattia','Закарпатська','Transcarpatie'],'21':['Ternopil','Тернопільська','Ternopil'],'26':['Chernivtsi','Чернівецька','Tchernivtsi'],'18':['Odesa','Одеська','Odessa'],'17':['Mykolaiv','Миколаївська','Mykolaïv'],'29':['Crimea','Крим','Crimée'],'4':['Vinnytsia','Вінницька','Vinnytsia'],'3':['Khmelnytskyi','Хмельницька','Khmelnytskyï'],'24':['Cherkasy','Черкаська','Tcherkassy'],'19':['Poltava','Полтавська','Poltava'],'9':['Dnipropetrovsk','Дніпропетровська','Dnipropetrovsk'],'15':['Kirovohrad','Кіровоградська','Kirovohrad'],'31':['Kyiv','Київ','Kyiv'],'30':['Sevastopol','Севастополь','Sébastopol']};
const LI=()=>LANG==='uk'?1:LANG==='fr'?2:0;
const oblName=uid=>(OBL_N[uid]||[uid,uid,uid])[LI()];
// "<name> oblast" in the current language (uk adds the adjective form + область; fr "oblast de X")
const oblFull=uid=>uid==='31'?oblName('31'):LANG==='uk'?oblName(uid)+' область':LANG==='fr'?'oblast de '+oblName(uid):oblName(uid)+' oblast';
// "towards <oblast>" needs the genitive in Ukrainian: «у бік Київської області», not «у бік Київська область».
// Every oblast adjective ends in -ська/-цька, so one ending does the whole list; Крим and Київ are not adjectives.
